select lives_ok($$insert into public.saved_reports(organisation_id,name,query) values ('10000000-0000-0000-0000-000000000001','New report','{}')$$,'insights owner creates report');
select throws_ok($$insert into public.saved_reports(organisation_id,name,query) values ('10000000-0000-0000-0000-000000000002','Foreign report','{}')$$,'42501',null,'owner cannot create report in another organisation');
select lives_ok($$update public.saved_reports set name = 'Edited' where name = 'New report'$$,'owner updates report');
select is((select count(*) from public.saved_reports where name = 'Edited'),1::bigint,'report update took effect');
select throws_ok($$update public.saved_reports set organisation_id = '10000000-0000-0000-0000-000000000002' where name = 'Edited'$$,'42501',null,'report cannot move into another organisation');
select lives_ok($$delete from public.saved_reports where name = 'Edited'$$,'owner deletes report');
select is((select count(*) from public.saved_reports where name = 'Edited'),0::bigint,'report deletion took effect');
reset role;
select tests.act_as('supplier_member');
with changed as (update public.saved_reports set name = 'Denied' returning id) select is(count(*),0::bigint,'supplier report update denied') from changed;
with changed as (delete from public.saved_reports returning id) select is(count(*),0::bigint,'supplier report delete denied') from changed;
reset role;
select tests.act_as('other_organisation_member');
with changed as (update public.saved_reports set name = 'Denied' where organisation_id = '10000000-0000-0000-0000-000000000001' returning id) select is(count(*),0::bigint,'foreign report update denied') from changed;
with changed as (delete from public.saved_reports where organisation_id = '10000000-0000-0000-0000-000000000001' returning id) select is(count(*),0::bigint,'foreign report delete denied') from changed;
