select tests.act_as('signed_in_shopper');
select throws_ok($$select * from public.rate_limit_buckets$$,'42501',null,'shopper cannot read abuse counters');
select throws_ok($$select shopper_id from public.events$$,'42501',null,'live feed cannot expose shopper identity');
-- This local PostgreSQL image crashes on a direct denied function EXECUTE.
-- Inspect the real ACL without broadening access to avoid that engine failure.
select ok(not has_function_privilege(current_user,'public.claim_job(text[],text)','EXECUTE'),'shopper has no job claim capability');
reset role;
update public.memberships set store_ids = '{}' where profile_id = tests.get_supabase_uid('organisation_manager');
select tests.act_as('organisation_manager');
select is((select count(*) from public.events),0::bigint,'empty manager store scope denies live feed');
select is((select count(*) from public.metrics_daily),0::bigint,'empty manager store scope denies daily metrics');
select is((select count(*) from public.metrics_hourly),0::bigint,'empty manager store scope denies hourly metrics');
select is((select count(*) from public.saved_reports),0::bigint,'scoped manager cannot read organisation-wide reports');
reset role;
select * from finish();
